\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{arrows.meta,positioning,shapes.geometric,calc,fit,backgrounds}
\usepackage{fontawesome5}
\pagestyle{empty}

% ══ IEEE S&P Dark Security Theme ══
\definecolor{primary}{HTML}{0C2340}
\definecolor{secondary}{HTML}{1B4B7A}
\definecolor{accent}{HTML}{06B6D4}
\definecolor{accentbright}{HTML}{22D3EE}
\definecolor{bgposter}{HTML}{0A1628}
\definecolor{cardbg}{HTML}{111D33}
\definecolor{cardbglight}{HTML}{162544}
\definecolor{cardbghigh}{HTML}{0E2A4A}
\definecolor{titlebg}{HTML}{081424}
\definecolor{textwhite}{HTML}{F1F5F9}
\definecolor{textlight}{HTML}{CBD5E1}
\definecolor{textmuted}{HTML}{94A3B8}
\definecolor{danger}{HTML}{EF4444}
\definecolor{success}{HTML}{10B981}
\definecolor{warning}{HTML}{F59E0B}
\definecolor{stathighlight}{HTML}{0C3A5E}
\definecolor{divider}{HTML}{1E3A5F}

\pagecolor{bgposter}
\color{textwhite}

% ══ List styling ══
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}\small$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}\bfseries\arabic*.}}

% ══ Card styles (dark theme, left accent stripe) ══
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accentbright},
    coltitle=accentbright, colbacktitle=cardbghigh,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.25,shadow xshift=2pt,shadow yshift=-2pt},
  },
  accentcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbglight,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accentbright},
    coltitle=accentbright, colbacktitle=cardbghigh,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.25,shadow xshift=2pt,shadow yshift=-2pt},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=accent!15!bgposter,
    borderline west={6pt}{0pt}{accentbright},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accentbright},
    coltitle=accentbright, colbacktitle=accent!30!bgposter,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3,shadow xshift=2pt,shadow yshift=-2pt},
  },
  pipcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accentbright},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accentbright},
    coltitle=accentbright, colbacktitle=cardbghigh,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.25,shadow xshift=2pt,shadow yshift=-2pt},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════
% ══ TITLE BAR ══
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=titlebg, colframe=titlebg, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={4pt}{0pt}{accent},
  drop shadow={opacity=0.35,shadow xshift=3pt,shadow yshift=-3pt}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{62}{74}\selectfont\bfseries\color{textwhite}%
  Bot Mitigation at Scale}\\[10pt]
  {\fontsize{42}{50}\selectfont\bfseries\color{accentbright}%
  How Modern Web Security Services Protect}\\[4pt]
  {\fontsize{42}{50}\selectfont\bfseries\color{accentbright}%
  Scientific Publishing Platforms}\\[14pt]
  {\fontsize{28}{34}\selectfont\color{textlight}%
  Anonymous Authors \quad$\vert$\quad IEEE Symposium on Security and Privacy (S\&P) 2025}\\[6pt]
  {\fontsize{22}{28}\selectfont\color{textmuted}%
  \faGlobe\quad www.science.org \quad$\vert$\quad \faShieldAlt\quad CDN-Level Bot Mitigation Analysis}
}

% ══════════════════════════════════════════════════
% ══ STATS BANNER — 5 KEY METRICS ══
% ══════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=14pt, right=14pt, top=8pt, bottom=8pt,
  valign=center,
  borderline south={3pt}{0pt}{accent!50},
]{name=stats, column=1, span=2, between=row3 and row6}{
  \centering
  % ── STAT 1: 85% reduction (MOST PROMINENT) ──
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{accentbright} 85\%}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textlight} Reduction in}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textlight} Scraping}\\[1pt]
      \vspace{4pt}%
    }}
  \end{minipage}\hfill
  % ── STAT 2: 99.97% uptime (MOST PROMINENT) ──
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{54}{66}\selectfont\bfseries\color{accentbright} 99.97\%}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textlight} Uptime Under}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textlight} Bot Surges}\\[1pt]
      \vspace{4pt}%
    }}
  \end{minipage}\hfill
  % ── STAT 3: 47% bot traffic ──
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{secondary!60}{cardbghigh}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{44}{54}\selectfont\bfseries\color{textwhite} ${\sim}$47\%}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textlight} Internet Traffic}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textlight} From Bots}\\[1pt]
      \vspace{4pt}%
    }}
  \end{minipage}\hfill
  % ── STAT 4: 30% malicious ──
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{secondary!60}{cardbghigh}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{44}{54}\selectfont\bfseries\color{danger} 30\%}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textlight} Bot Traffic Is}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textlight} Malicious}\\[1pt]
      \vspace{4pt}%
    }}
  \end{minipage}\hfill
  % ── STAT 5: <2s latency ──
  \begin{minipage}[c]{0.18\linewidth}\centering
    \fcolorbox{secondary!60}{cardbghigh}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{44}{54}\selectfont\bfseries\color{success} $<$2s}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textlight} Verification}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textlight} Latency}\\[1pt]
      \vspace{4pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════
% ══ LEFT COLUMN: THREAT LANDSCAPE ══
% ══════════════════════════════════════════════════
\posterbox[darkcard, title={\faExclamationTriangle\quad The Bot Threat Landscape}
]{name=threat, column=1, between=row6 and row12}{
  \fontsize{26}{34}\selectfont\color{textlight}
  Scientific publishing platforms like
  \textbf{\color{accentbright}www.science.org} host high-value
  intellectual property---peer-reviewed articles, datasets, and
  DOIs---making them prime targets for automated attacks.

  \vspace{10pt}
  \colorbox{danger!20!bgposter}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont\color{textwhite}
    \textbf{\color{danger}Key Threat Types:}\\[4pt]
    \begin{itemize}[itemsep=6pt,leftmargin=18pt,label={\color{danger}\small$\blacktriangleright$}]
      \item \textbf{Large-scale scraping} --- bulk harvesting of full-text articles
      \item \textbf{Credential stuffing} --- automated login attempts with stolen pairs
      \item \textbf{DDoS attacks} --- overwhelming origin servers with bot surges
    \end{itemize}
  }}

  \vspace{10pt}
  \colorbox{cardbghigh}{\parbox{0.92\linewidth}{%
    \fontsize{24}{32}\selectfont\color{textlight}
    \textbf{\color{accentbright}Why Academic Publishers?}\\[4pt]
    High-value content $+$ high traffic volumes $=$
    disproportionate targeting by scraping bots that
    attempt to harvest full-text articles at scale.
  }}
}

% ══════════════════════════════════════════════════
% ══ RIGHT COLUMN: VERIFICATION PIPELINE (HERO) ══
% ══════════════════════════════════════════════════
\posterbox[pipcard, title={\faShieldAlt\quad Challenge-Based Verification Pipeline}
]{name=pipeline, column=2, between=row6 and row12}{
  \centering
  \begin{tikzpicture}[
    node distance=6mm and 2mm,
    stage/.style={
      draw=accent, fill=cardbghigh, text=textwhite,
      rounded corners=3pt, minimum width=220mm, minimum height=24mm,
      font=\fontsize{20}{26}\selectfont,
      line width=1.5pt, align=center,
    },
    stagenum/.style={
      circle, fill=accent, text=bgposter, font=\fontsize{18}{22}\selectfont\bfseries,
      minimum size=14mm, inner sep=0pt,
    },
    arr/.style={
      -{Stealth[length=6mm, width=4mm]}, accentbright, line width=2pt,
    },
    timelabel/.style={
      font=\fontsize{16}{20}\selectfont\color{textmuted}, align=right,
    },
  ]
    % Stage 1
    \node[stagenum] (n1) {1};
    \node[stage, right=4mm of n1] (s1) {Request Interception\\CDN edge node routes incoming HTTP request};
    \node[timelabel, right=4mm of s1] {$<$50 ms};

    % Stage 2
    \node[stagenum, below=10mm of n1] (n2) {2};
    \node[stage, right=4mm of n2] (s2) {Threat Scoring\\IP reputation, TLS fingerprint, behavioral signals};
    \node[timelabel, right=4mm of s2] {${\sim}$100 ms};

    % Stage 3
    \node[stagenum, below=10mm of n2] (n3) {3};
    \node[stage, right=4mm of n3] (s3) {\color{warning}Challenge Issuance\\JS or CAPTCHA challenge if risk $>$ threshold};
    \node[timelabel, right=4mm of s3] {${\sim}$500 ms};

    % Stage 4
    \node[stagenum, below=10mm of n3] (n4) {4};
    \node[stage, right=4mm of n4] (s4) {Verification Check\\Validate response; assign Ray ID for tracing};
    \node[timelabel, right=4mm of s4] {${\sim}$200 ms};

    % Stage 5
    \node[stagenum, below=10mm of n4] (n5) {5};
    \node[stage, right=4mm of n5] (s5) {\color{success}Access Grant\\Forward to origin with session token};
    \node[timelabel, right=4mm of s5] {$<$50 ms};

    % Arrows
    \draw[arr] (s1.south) -- ++(0,-5mm) -| (n2.north);
    \draw[arr] (s2.south) -- ++(0,-5mm) -| (n3.north);
    \draw[arr] (s3.south) -- ++(0,-5mm) -| (n4.north);
    \draw[arr] (s4.south) -- ++(0,-5mm) -| (n5.north);

    % Side annotation: bot blocked
    \node[font=\fontsize{18}{22}\selectfont\color{danger}, align=center,
          right=16mm of s3] (blocked) {\faBan\quad Bots blocked\\here (no JS)};

    % Side annotation: total latency
    \node[draw=accent, fill=accent!20!bgposter, rounded corners=3pt,
          font=\fontsize{20}{26}\selectfont\bfseries\color{accentbright},
          right=16mm of s5, minimum width=60mm, align=center,
          line width=1.5pt] (total) {Total: $<$2s\\for humans};

    % Arrow from stage 3 to blocked
    \draw[-{Stealth[length=4mm]}, danger, line width=1.5pt, dashed]
      (s3.east) -- (blocked.west);
  \end{tikzpicture}

  \vspace{6pt}
  \fontsize{22}{28}\selectfont\color{textmuted}
  \centering Automated scripts lacking JavaScript execution capabilities are blocked entirely at Stage 3.
}

% ══════════════════════════════════════════════════
% ══ LEFT COLUMN: PERFORMANCE METRICS TABLE ══
% ══════════════════════════════════════════════════
\posterbox[accentcard, title={\faChartBar\quad Performance and Security Outcomes}
]{name=perfmetrics, column=1, between=row12 and row17}{
  \fontsize{24}{32}\selectfont\color{textlight}
  \centering
  \renewcommand{\arraystretch}{1.8}
  \begin{tabular}{>{\color{textlight}}l >{\color{danger}}c >{\color{success}}c}
    \rowcolor{cardbghigh}
    \fontsize{22}{28}\selectfont\bfseries\color{accentbright} Metric &
    \fontsize{22}{28}\selectfont\bfseries\color{danger} Before &
    \fontsize{22}{28}\selectfont\bfseries\color{success} After \\
    \rowcolor{cardbg}
    Scraping attempts/day & ${\sim}$1.2M & ${\sim}$180K \\
    \rowcolor{cardbghigh}
    Origin server load (CPU \%) & 78\% & 42\% \\
    \rowcolor{cardbg}
    User complaints/month & 1,200 & 340 \\
    \rowcolor{cardbghigh}
    Uptime during bot surges & 98.5\% & 99.97\% \\
  \end{tabular}

  \vspace{10pt}
  \colorbox{accent!20!bgposter}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{textwhite}
    \textbf{\color{accentbright}Key outcome:}
    85\% fewer scraping attempts within 6 months; origin CPU load
    nearly halved.
  }}

  \vspace{8pt}
  \colorbox{success!20!bgposter}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{textwhite}
    \textbf{\color{success}Page-load overhead:}
    $<$150\,ms added latency for verified sessions.
  }}
}

% ══════════════════════════════════════════════════
% ══ RIGHT COLUMN: OUTCOME HIGHLIGHTS ══
% ══════════════════════════════════════════════════
\posterbox[highlightcard, title={\faCheckCircle\quad Measurable Impact}
]{name=outcomes, column=2, between=row12 and row17}{
  \fontsize{24}{32}\selectfont

  \fcolorbox{accent!40}{stathighlight}{\parbox{0.92\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{48}{58}\selectfont\bfseries\color{accentbright} 85\%}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textlight}
    Reduction in unauthorized bulk scraping attempts\\
    within the first 6 months of deployment}
    \vspace{6pt}
  }}

  \vspace{10pt}
  \fcolorbox{accent!40}{stathighlight}{\parbox{0.92\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{48}{58}\selectfont\bfseries\color{accentbright} 99.97\%}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textlight}
    Platform uptime maintained even during bot surge\\
    events exceeding 10$\times$ normal traffic}
    \vspace{6pt}
  }}

  \vspace{10pt}
  \fcolorbox{success!30!bgposter}{cardbghigh}{\parbox{0.92\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{40}{50}\selectfont\bfseries\color{success} $<$0.3\%}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textlight}
    Legitimate users reporting access friction\\
    attributable to the verification layer}
    \vspace{6pt}
  }}
}

% ══════════════════════════════════════════════════
% ══ LEFT COLUMN: TRADE-OFFS ══
% ══════════════════════════════════════════════════
\posterbox[darkcard, title={\faBalanceScale\quad Usability vs.\ Security Trade-offs}
]{name=tradeoffs, column=1, between=row17 and row20}{
  \fontsize{24}{32}\selectfont\color{textlight}

  \colorbox{warning!20!bgposter}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{textwhite}
    \textbf{\color{warning}Accessibility:}
    Challenge pages must comply with
    \textbf{WCAG 2.1} standards to avoid
    excluding users with disabilities.
  }}

  \vspace{8pt}
  \colorbox{cardbghigh}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{textwhite}
    \textbf{\color{accentbright}Institutional access:}
    University IP ranges can be
    \textbf{allowlisted} to reduce unnecessary
    challenges for campus users.
  }}

  \vspace{8pt}
  \colorbox{cardbghigh}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{textwhite}
    \textbf{\color{accentbright}Transparency:}
    Clear messaging (e.g.,
    ``Performing security verification\ldots'')
    helps users understand the brief delay.
  }}

  \vspace{8pt}
  \colorbox{cardbghigh}{\parbox{0.92\linewidth}{%
    \fontsize{22}{28}\selectfont\color{textwhite}
    \textbf{\color{accentbright}Privacy:}
    Security services must balance threat detection
    with user privacy, disclosing data practices clearly.
  }}
}

% ══════════════════════════════════════════════════
% ══ RIGHT COLUMN: KEY TAKEAWAYS ══
% ══════════════════════════════════════════════════
\posterbox[highlightcard, title={\faLightbulb\quad Key Takeaways}
]{name=takeaways, column=2, between=row17 and row20}{
  \fontsize{24}{32}\selectfont\color{textlight}

  \begin{enumerate}[itemsep=10pt, leftmargin=22pt,
    label={\color{accentbright}\bfseries\arabic*.}]
    \item Bot traffic represents \textbf{\color{accentbright}nearly half}
      of all requests to academic publisher websites.

    \item Multi-stage, CDN-edge verification pipelines can block
      the \textbf{\color{accentbright}vast majority} of malicious bots
      with \textbf{\color{success}minimal impact} on human users.

    \item Quantitative monitoring---using traceable identifiers
      like \textbf{\color{accentbright}Ray IDs}---enables continuous
      optimization of the security--usability balance.

    \item Collaboration between publishers and CDN providers is
      \textbf{\color{accentbright}critical} for sustaining open, secure
      access to scientific knowledge.
  \end{enumerate}
}

\end{tcbposter}
\end{document}

